 auto has_class=[&](const std::string& wanted){const auto value=attr("class");size_t i=0;while(i<value.size()){while(i<value.size()&&class_space(value[i]))++i;size_t start=i;while(i<value.size()&&!class_space(value[i]))++i;if(value.substr(start,i-start)==wanted)return true;}return false;};
 const StyleFixture* best=nullptr;for(const auto&r:rules){bool matched=false;if(node.tag==Tag::P){if(r.selector==SelectorFixture::P)matched=true;else if(r.selector==SelectorFixture::ClassBeta)matched=has_class("beta");else matched=attr("id")=="alpha";}if(matched&&(!best||r.priority>best->priority))best=&r;}
